  'presentation.emptyStart': { en: 'Add a song or scripture to start.', tl: 'Magdagdag ng kanta o talata para magsimula.', es: 'Añade una canción o un pasaje para empezar.', pt: 'Adicione uma música ou passagem para começar.', fr: 'Ajoutez un chant ou un passage pour commencer.', it: 'Aggiungi un canto o un passo biblico per iniziare.', ko: '찬양이나 성경 구절을 추가해 시작하세요.', zh: '添加歌曲或经文即可开始。', id: 'Tambahkan lagu atau ayat untuk memulai.', hi: 'शुरू करने के लिए गीत या वचन जोड़ें।', ta: 'தொடங்க ஒரு பாடல் அல்லது வேத வசனம் சேர்க்கவும்.', ru: 'Добавьте песню или отрывок Писания.', uk: 'Додайте пісню або уривок Писання.' },

