  'presentation.advanceOnLoopHint': { en: 'Auto-advance: next slide every {n} s, looping', tl: 'Auto-advance: susunod na slide bawat {n} s, umuulit', es: 'Avance automático: siguiente diapositiva cada {n} s, en bucle', pt: 'Avanço automático: próximo slide a cada {n} s, em loop', fr: 'Défilement auto : diapo suivante toutes les {n} s, en boucle', it: 'Avanzamento automatico: diapositiva successiva ogni {n} s, in loop', ko: '자동 넘김: {n}초마다 다음 슬라이드, 반복', zh: '自动翻页：每 {n} 秒下一张，循环', id: 'Maju otomatis: slide berikutnya tiap {n} dtk, berulang', hi: 'ऑटो-आगे: हर {n} से. अगली स्लाइड, दोहराते हुए', ta: 'தானாக முன்னேறு: ஒவ்வொரு {n} வி. அடுத்த ஸ்லைடு, சுழற்சி', ru: 'Автопереход: следующий слайд каждые {n} с, по кругу', uk: 'Автоперехід: наступний слайд кожні {n} с, по колу' },
  'presentation.advanceOffHint': { en: 'Move to the next slide on a timer while this item is live', tl: 'Awtomatikong lumipat sa susunod na slide habang naka-live ang item na ito', es: 'Pasar a la siguiente diapositiva automáticamente mientras este elemento está en vivo', pt: 'Passar ao próximo slide automaticamente enquanto este item está ao vivo', fr: 'Passer automatiquement à la diapo suivante pendant que cet élément est à l’écran', it: 'Passa alla diapositiva successiva in automatico mentre questo elemento è in onda', ko: '이 항목이 라이브일 때 자동으로 다음 슬라이드로', zh: '此项目直播时自动切换到下一张', id: 'Pindah ke slide berikutnya otomatis saat item ini live', hi: 'यह आइटम लाइव रहते हुए अपने आप अगली स्लाइड पर जाएँ', ta: 'இந்த உருப்படி நேரலையில் இருக்கும்போது தானாக அடுத்த ஸ்லைடுக்குச் செல்', ru: 'Автоматически листать слайды, пока элемент в эфире', uk: 'Автоматично гортати слайди, поки елемент в ефірі' },
  'presentation.secondsShort': { en: '{n}s', tl: '{n}s', es: '{n} s', pt: '{n} s', fr: '{n} s', it: '{n} s', ko: '{n}초', zh: '{n}秒', id: '{n} dtk', hi: '{n} से.', ta: '{n} வி.', ru: '{n} с', uk: '{n} с' },
