  'presentation.autoAdvance': { en: 'Auto-advance', tl: 'Auto-advance', es: 'Avance auto.', pt: 'Avanço auto.', fr: 'Défilement auto', it: 'Avanz. auto', ko: '자동 넘김', zh: '自动翻页', id: 'Maju otomatis', hi: 'ऑटो-आगे', ta: 'தானியங்கு', ru: 'Автопереход', uk: 'Автоперехід' },
  'presentation.nextSlideEvery': { en: 'Next slide every', tl: 'Susunod na slide bawat', es: 'Siguiente diapositiva cada', pt: 'Próximo slide a cada', fr: 'Diapo suivante toutes les', it: 'Diapositiva successiva ogni', ko: '다음 슬라이드 간격', zh: '翻页间隔', id: 'Slide berikutnya tiap', hi: 'अगली स्लाइड हर', ta: 'அடுத்த ஸ்லைடு இடைவெளி', ru: 'Следующий слайд каждые', uk: 'Наступний слайд кожні' },
