  'presentation.secondsWord': { en: 'seconds', tl: 'segundo', es: 'segundos', pt: 'segundos', fr: 'secondes', it: 'secondi', ko: '초', zh: '秒', id: 'detik', hi: 'सेकंड', ta: 'விநாடிகள்', ru: 'секунд', uk: 'секунд' },
  'presentation.loopLabel': { en: 'Loop: start again after the last slide', tl: 'Ulitin: magsimula muli pagkatapos ng huling slide', es: 'Bucle: volver a empezar tras la última', pt: 'Loop: recomeçar após o último slide', fr: 'Boucle : recommencer après la dernière diapo', it: 'Loop: ricomincia dopo l’ultima diapositiva', ko: '반복: 마지막 슬라이드 후 처음부터', zh: '循环：最后一张后从头开始', id: 'Ulang: mulai lagi setelah slide terakhir', hi: 'दोहराएँ: आख़िरी स्लाइड के बाद फिर से शुरू', ta: 'சுழற்சி: கடைசி ஸ்லைடுக்குப் பின் மீண்டும் தொடங்கு', ru: 'По кругу: после последнего слайда — сначала', uk: 'По колу: після останнього слайда — спочатку' },
  'presentation.advanceNote': { en: 'Runs while this item is live. Next or Back restarts the timer.', tl: 'Tumatakbo habang naka-live ang item. Nire-restart ng Susunod o Bumalik ang timer.', es: 'Funciona mientras el elemento está en vivo. Siguiente o Atrás reinician el temporizador.', pt: 'Funciona enquanto o item está ao vivo. Próximo ou Voltar reinicia o timer.', fr: 'Actif tant que l’élément est à l’écran. Suivant ou Retour relance le minuteur.', it: 'Attivo mentre l’elemento è in onda. Avanti o Indietro riavviano il timer.', ko: '이 항목이 라이브일 때 작동합니다. 다음/이전을 누르면 타이머가 다시 시작됩니다.', zh: '在此项目直播时运行。按下一张或上一张会重新计时。', id: 'Berjalan saat item ini live. Berikutnya atau Kembali mengulang timer.', hi: 'यह आइटम लाइव रहने पर चलता है। अगला या पीछे दबाने से टाइमर फिर शुरू होता है।', ta: 'இந்த உருப்படி நேரலையில் இருக்கும்போது இயங்கும். அடுத்து அல்லது பின் டைமரை மீண்டும் தொடங்கும்.', ru: 'Работает, пока элемент в эфире. «Далее» или «Назад» перезапускают таймер.', uk: 'Працює, поки елемент в ефірі. «Далі» або «Назад» перезапускають таймер.' },
  'presentation.transposeHint': { en: 'Transpose the chords on stage screens for this service only. The song in the library stays as it is.', tl: 'I-transpose ang mga chord sa stage screen para sa serbisyong ito lang. Hindi babaguhin ang kanta sa library.', es: 'Transporta los acordes de las pantallas de escenario solo en este culto. La canción de la biblioteca no cambia.', pt: 'Transpõe os acordes nas telas de palco só neste culto. A música na biblioteca não muda.', fr: 'Transpose les accords sur les écrans de scène pour ce culte seulement. Le chant de la bibliothèque ne change pas.', it: 'Traspone gli accordi sugli schermi del palco solo per questo servizio. Il canto in libreria resta com’è.', ko: '이 예배에서만 무대 화면의 코드를 조옮김합니다. 보관함의 찬양은 그대로입니다.', zh: '仅在本场聚会中移调舞台屏幕上的和弦，曲库中的歌曲不变。', id: 'Transpos kord di layar panggung hanya untuk ibadah ini. Lagu di pustaka tetap.', hi: 'केवल इस सेवा के लिए स्टेज स्क्रीन पर कॉर्ड ट्रांसपोज़ करें। लाइब्रेरी का गीत वैसा ही रहेगा।', ta: 'இந்த ஆராதனைக்கு மட்டும் மேடைத் திரைகளில் கார்டுகளை மாற்று. நூலகப் பாடல் மாறாது.', ru: 'Транспонировать аккорды на сценических экранах только в этом служении. Песня в библиотеке не меняется.', uk: 'Транспонувати акорди на сценічних екранах лише в цьому служінні. Пісня в бібліотеці не зміниться.' },
